public class Element_nextElementSibling_TriageGen1Test {

    @Test
    public void nextElementSibling_NoSiblings_ReturnNull() {
        Element element = new Element(Tag.valueOf("p"), "baseUri", Attributes.NONE);
        assertNull(element.nextElementSibling());
    }

    @Test
    public void nextElementSibling_OnlyOneSibling_ReturnSibling() {
        Element parent = new Element(Tag.valueOf("div"), "baseUri", Attributes.NONE);
        parent.appendChild(new TextNode("text"));
        Element element = new Element(Tag.valueOf("p"), "baseUri", Attributes.NONE);
        parent.appendChild(element);
        assertEquals("text", parent.children().get(0).toString());
        assertEquals(element, parent.children().get(1));
        assertEquals("text", parent.children().get(1).toString());
        assertEquals(element, parent.children().get(1));
        assertEquals(parent.children().get(1), element.nextElementSibling());
    }

